ATL_SRC.push(['@atl/inmode.js', 0, `// Inbound by rail vs truck, from the Billing Activity lines (rules from Josh, Nov 2026):
//  - An inbound line whose Carrier says CSX came by rail (Electrolit); so did a line whose PO names a railcar (a known
//    reporting mark + number — Smurfit Westrock). Anything else came by truck.
//  - The rail car number is in the Note column ("TBOX 633587"). Every line for the same car number within 7 days
//    is ONE rail car (six lines on the same day = one car); the same car seen again more than 7 days later is a new trip.
//  - Truck loads are counted one per BL #.
import { isISO } from '@atl/util.js';

export const isRail = carrier => /\\bCSX\\b/i.test(String(carrier || ''));
// Smurfit Westrock (Nov 2026): the Carrier column holds routing codes, so a rail car is found in the PO field
// ("WHSE - PIPATL TBOX 662062", "NORCROSS - XDK TBOX661306"). Only these railcar reporting marks count — Josh confirmed
// LT… and TR… are trailers, and XDK / CSI numbers are not cars. Add a mark here when a new one turns up.
export const RAIL_MARKS = ['TBOX', 'FBOX', 'TOBX', 'ABOX', 'RBOX', 'CBOX', 'XBOX', 'BKTY', 'FGLK', 'LRS', 'BNSF', 'UP', 'CSXT', 'NS', 'NSHR', 'CN', 'IC', 'CP', 'SOO', 'KCS', 'GTW', 'DWC', 'WC',
  'ATW', 'TTGX', 'GATX', 'PLMX', 'MP', 'SP', 'CR', 'CRYX', 'FXE', 'NKCR', 'ICG', 'BCOL', 'CNA', 'MILW', 'PCN', 'AOK', 'CEFX', 'ADMX'];
const MARK_RE = new RegExp(\`\\\\b(\${RAIL_MARKS.join('|')})\\\\s*-?\\\\s*(\\\\d{4,7})\\\\b\`);
/** A rail car named in a PO ("… TBOX661306" → "TBOX 661306"), or ''. Only the reporting marks above count. */
export function railCarInPo(po) { const m = String(po || '').toUpperCase().match(MARK_RE); return m ? \`\${m[1]} \${m[2]}\` : ''; }
/** How a line came in: rail (Carrier CSX → car from the Note; or a railcar in the PO → that car) or truck. */
export function lineMode(l) {
  if (isRail(l.carrier)) return { rail: true, car: railCarOf(l.note) || railCarInPo(l.po) };
  const car = railCarInPo(l.po);
  return car ? { rail: true, car } : { rail: false, car: '' };
}
/** The rail car number in a note ("tbox 633587", "TBOX-633587" → "TBOX 633587"), or '' when there isn't one. */
export function railCarOf(note) {
  const m = String(note || '').toUpperCase().match(/\\b([A-Z]{2,4})\\s*-?\\s*(\\d{4,7})\\b/);
  return m ? \`\${m[1]} \${m[2]}\` : '';
}
export const SAME_CAR_DAYS = 7;
const dayNo = iso => Math.round(Date.parse(iso + 'T12:00:00Z') / 864e5);

/**
 * Rail car trips from [{ car, date }] (any order, duplicates fine): the same car within SAME_CAR_DAYS of its last line
 * is the same trip. A line with no car number counts one car per day. → [{ car, date (first line), last }]
 */
export function railTrips(list) {
  const items = list.filter(x => isISO(x.date)).map(x => ({ car: x.car || \`NO CAR # \${x.date}\`, date: x.date })).sort((a, b) => a.car.localeCompare(b.car) || a.date.localeCompare(b.date));
  const trips = [];
  for (const x of items) {
    const t = trips.at(-1);
    if (t && t.car === x.car && dayNo(x.date) - dayNo(t.last) <= SAME_CAR_DAYS) t.last = x.date;
    else trips.push({ car: x.car, date: x.date, last: x.date });
  }
  return trips.sort((a, b) => a.date.localeCompare(b.date));
}

/**
 * One customer's inbound lines for a week or file → { railIn, truckIn (main unit), railSkidsIn, truckSkidsIn,
 * truckLoadsIn (one per BL #), railCarsIn: [{car, date}] (one per car and day) }.
 * amountOf(line) gives the line's amount in the main unit (skids for pallets, tons for 6021).
 */
export function inboundSplit(lines, amountOf = l => +l.skids || 0) {
  const tagged = lines.map(l => ({ l, ...lineMode(l) }));
  const rail = tagged.filter(x => x.rail).map(x => x.l), truck = tagged.filter(x => !x.rail).map(x => x.l);
  const sum = (ls, f) => Math.round(ls.reduce((a, l) => a + (+f(l) || 0), 0) * 1000) / 1000;
  const cars = new Map();
  for (const x of tagged.filter(x => x.rail)) { const k = \`\${x.car}|\${x.l.date}\`; if (!cars.has(k)) cars.set(k, { car: x.car, date: x.l.date }); }
  const bls = new Set(); truck.forEach((l, i) => bls.add(l.bl || \`#\${i}\`));
  return { railIn: sum(rail, amountOf), truckIn: sum(truck, amountOf), railSkidsIn: sum(rail, l => l.skids), truckSkidsIn: sum(truck, l => l.skids), truckLoadsIn: bls.size, railCarsIn: [...cars.values()] };
}`]);

