ATL_SRC.push(['@atl/intake.js', 0, `// "Drop any file": recognize a file and hand it to the page that already reads it, as if it had been dropped
// there. Works from the drop box on Weekly Entry, or by dropping a file anywhere in the app that isn't a drop zone.
//   Rail OTIF KPI workbook / MHE Fleet Register  → Import Excel (admins)
//   Billing Activity workbooks                    → Weekly Entry ▸ Customer Throughput
//   WMS move export (Username, ActivityDate …)    → Weekly Entry ▸ Operator Throughput
//   HR "Detailed Hours Overview" or "Detailed Calculated Time (Counters)" PDF → Weekly Entry ▸ HR Time & Labor
//   Railroad notification PDF / email             → Weekly Entry ▸ Rail Records
//   Dock schedule export (6021_Inbound_….xlsx)    → Weekly Entry ▸ Truck Appointments
//   MHE invoice PDF                               → MHE Fleet ▸ Maintenance
//   GoAudits email (Electrolit OS&D / WestRock ACR) → that scorecard's Data drop (the attached PDF is read)
// A PDF whose name doesn't say which it is gets a short "Which is this?" choice.
import { store } from '@atl/store.js';
import { esc, toast } from '@atl/util.js';
import { isTruckFile } from '@atl/trucks.js';

const SHEETJS = 'https://cdn.sheetjs.com/xlsx-0.20.3/package/xlsx.mjs';
const T = {
  kpi: { label: 'Rail OTIF KPI workbook', hash: '#/import', input: '[data-file]', admin: true },
  mhe: { label: 'MHE Fleet Register', hash: '#/import', input: '[data-file]', admin: true },
  billing: { label: 'Billing Activity (customer throughput)', hash: '#/weekly', tab: 'customer', drop: '[data-tp-drop]' },
  wms: { label: 'WMS move export (operator throughput)', hash: '#/weekly', tab: 'operator', drop: '[data-op-drop]' },
  hr: { label: 'HR hours (Detailed Hours Overview or Calculated Time Counters)', hash: '#/weekly', tab: 'labor', drop: '[data-drop]' },
  rail: { label: 'Railroad notification', hash: '#/weekly', tab: 'rail', drop: '[data-rail-drop]' },
  trucks: { label: 'Dock schedule export (truck appointments)', hash: '#/weekly', tab: 'trucks', drop: '[data-trk-drop]' },
  invoice: { label: 'MHE invoice', hash: '#/mhe?tab=maintenance', drop: '[data-inv-drop]' },
  ncr: { label: 'GoAudits Electrolit OS&D audit (NCR)', hash: '#/electrolit?tab=drops', drop: '[data-drop="ncr"]', page: 'the Electrolit scorecard' },
  acr: { label: 'GoAudits WestRock arrival condition report (ACR)', hash: '#/westrock?tab=drop', drop: '[data-drop]', page: 'the WestRock scorecard' },
};

/** What kind of file is this? Returns a key of T, or '' when it can't tell. */
async function kindOf(f) {
  const n = f.name.toLowerCase(), ext = n.split('.').pop();
  if (isTruckFile(f.name)) return 'trucks';
  // GoAudits emails ("Audit Results for ELECTROLIT USA - Score …"): the audit PDF is attached.
  if (['msg', 'eml'].includes(ext) && /audit results|goaudits|\\bacr\\b|arrival condition/.test(n)) {
    if (/electrolit/.test(n)) return 'ncr';
    if (/westrock|west rock|smurfit|wrk|\\bacr\\b|arrival/.test(n)) return 'acr';
    return '';
  }
  if (['msg', 'eml'].includes(ext) || /pbnotify|notifyprt|notif/.test(n)) return 'rail';
  if (ext === 'pdf') {
    if (/hours|overview|payroll|time|counter/.test(n)) return 'hr';
    if (/invoice|inv[\\s_-]?\\d|work ?order|\\bpm\\b|repair/.test(n)) return 'invoice';
    return '';
  }
  if (ext === 'csv') return 'wms';
  if (!['xlsx', 'xlsm', 'xls'].includes(ext)) return '';
  if (/billing ?activity/.test(n)) return 'billing';
  try {
    const XLSX = await import(SHEETJS), buf = await f.arrayBuffer();
    const wb = XLSX.read(buf, { type: 'array', sheetRows: 12 });
    const names = wb.SheetNames;
    if (names.includes('Fleet Register') && !names.includes('OTIF Log')) return 'mhe';
    if (names.includes('OTIF Log') || names.includes('Settings')) return 'kpi';
    const head = XLSX.utils.sheet_to_csv(wb.Sheets[names[0]]).toUpperCase();
    if (head.includes('USERNAME') && head.includes('ACTIVITYDATE')) return 'wms';
    if (/BILLING|ACTIVITY|PALLETS|TONS/.test(head)) return 'billing';
  } catch (e) { console.warn('intake: could not read', f.name, e); }
  return '';
}

const until = (sel, ms = 6000) => new Promise(res => {
  const t0 = Date.now(), tick = () => { const el = document.querySelector(sel); if (el || Date.now() - t0 > ms) res(el); else setTimeout(tick, 100); };
  tick();
});

/** "Which is this?" for a file the app can't place by itself. */
function choose(f) {
  return new Promise(resolve => {
    const d = document.createElement('dialog');
    d.className = 'ask';
    const opts = Object.entries(T).filter(([, t]) => !t.admin || store.can('admin'));
    d.innerHTML = \`<form method="dialog"><p class="ask-q">Which file is “\${esc(f.name)}”?</p><p class="ask-d">Pick one and the app opens the page that reads it.</p>
      <div class="intake-pick">\${opts.map(([k, t]) => \`<button type="submit" class="btn ghost" value="\${k}">\${esc(t.label)}</button>\`).join('')}</div>
      <div class="ask-btns"><button type="submit" class="btn ghost" value="">Cancel</button></div></form>\`;
    let done = false;
    const finish = v => { if (done) return; done = true; if (d.open) d.close(); d.remove(); resolve(v); };
    d.querySelector('form').addEventListener('submit', e => { e.preventDefault(); finish(e.submitter?.value || ''); });
    d.addEventListener('cancel', e => { e.preventDefault(); finish(''); });
    document.body.append(d); d.showModal();
  });
}

/** Send the dropped / chosen files to the right page. Files of different kinds go one kind at a time (the first). */
export async function routeFiles(list) {
  const files = [...list].filter(f => f && f.size !== undefined);
  if (!files.length) return;
  let kind = await kindOf(files[0]);
  if (!kind) kind = await choose(files[0]);
  if (!kind) return;
  const t = T[kind];
  if (t.admin && !store.can('admin')) { toast(\`\${t.label}: only an admin can import this workbook.\`, 'bad'); return; }
  if (!t.admin && !store.can('edit')) { toast('Your role can view but not enter data.', 'bad'); return; }
  const same = files.filter(f => f === files[0] || kind === 'billing' || kind === 'wms' || kind === 'rail' || kind === 'invoice' || kind === 'trucks' || kind === 'ncr' || kind === 'acr');
  toast(\`\${t.label}: opening \${t.page || (t.hash.includes('weekly') ? 'Weekly Entry' : t.hash.includes('mhe') ? 'MHE Fleet' : 'Import Excel')}…\`);
  if (location.hash !== t.hash) location.hash = t.hash;
  if (t.tab) {
    const btn = await until(\`[data-wk-tab="\${t.tab}"]\`);
    if (btn && !btn.classList.contains('on')) btn.click();
  }
  const dt = new DataTransfer(); same.forEach(f => dt.items.add(f));
  const el = await until(t.input || t.drop);
  if (!el) { toast(\`Couldn't open the \${t.label} drop box — drop the file there yourself.\`, 'bad'); return; }
  if (t.input) { el.files = dt.files; el.dispatchEvent(new Event('change', { bubbles: true })); }
  else el.dispatchEvent(new DragEvent('drop', { dataTransfer: dt, bubbles: true, cancelable: true }));
}

/** The drop box shown on Weekly Entry. */
export const intakeBox = () => \`<div class="wk-drop intake-drop" data-intake tabindex="0" role="button" aria-label="Drop any file, or click to choose one">
  <b>⬆ Drop any file here</b><span class="muted">HR hours PDF · Billing Activity workbooks · WMS move export · rail notices · dock schedule exports · MHE invoices · GoAudits emails\${store.can('admin') ? ' · KPI workbook · MHE Fleet Register' : ''}. The app recognizes it and opens the right step.</span>
  <input type="file" data-intake-pick multiple hidden></div>\`;

export function bindIntake(root) {
  const box = root.querySelector('[data-intake]'), pick = root.querySelector('[data-intake-pick]');
  if (!box) return;
  box.addEventListener('click', () => pick.click());
  box.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); pick.click(); } });
  box.addEventListener('dragover', e => { e.preventDefault(); box.classList.add('over'); });
  box.addEventListener('dragleave', () => box.classList.remove('over'));
  box.addEventListener('drop', e => { e.preventDefault(); e.stopPropagation(); box.classList.remove('over'); routeFiles(e.dataTransfer.files); });
  pick.addEventListener('change', () => { routeFiles(pick.files); pick.value = ''; });
}

/** Dropping a file anywhere that isn't a drop zone routes it too (instead of the browser opening the file). */
export function globalIntake() {
  const isZone = t => t?.closest?.('.wk-drop, .mf-drop, [data-drop], input[type=file], .modal, dialog');
  addEventListener('dragover', e => { if ([...(e.dataTransfer?.types || [])].includes('Files') && !isZone(e.target)) e.preventDefault(); });
  addEventListener('drop', e => {
    if (!e.dataTransfer?.files?.length || isZone(e.target) || !store.user) return;
    e.preventDefault(); routeFiles(e.dataTransfer.files);
  });
}`]);

