ATL_SRC.push(['@atl/mhedocs.js', 0, `// MHE Fleet documents and photos (invoices, manuals, warranty papers, inspection reports, certifications, photos).
// The list lives in "mheDocs" (one small record per file: unit, category, title, size, and a 240 px thumbnail for
// photos); the file itself is stored in "mheFiles", split into ~700 KB parts (Firestore allows ~1 MB per document)
// and read only when someone opens it. Demo Mode keeps the parts in this browser's IndexedDB. Photos are shrunk to
// 1600 px JPEG (same as the Safety Incident attachments).
import { store } from '@atl/store.js';
import { prepFile, dataBytes } from '@atl/forms/incident.js';
import { downloadBlob } from '@atl/util.js';

const PART = 700000; // base64 characters per stored part
export const MAX_MB = 15;
let dbp;
const db = () => (dbp ||= new Promise((res, rej) => {
  const r = indexedDB.open('atl-ops-mhe-files', 1);
  r.onupgradeneeded = () => r.result.createObjectStore('parts', { keyPath: 'id' });
  r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error);
}));
const idb = async (mode, fn) => { const d = await db(); return new Promise((res, rej) => { const t = d.transaction('parts', mode), q = fn(t.objectStore('parts')); t.oncomplete = () => res(q?.result); t.onerror = () => rej(t.error); t.onabort = () => rej(t.error); }); };

/** A small JPEG preview (data URL) of a photo, for the profile gallery. */
async function thumbOf(dataUrl) {
  try {
    const img = await createImageBitmap(await (await fetch(dataUrl)).blob()), k = Math.min(1, 240 / Math.max(img.width, img.height));
    const c = document.createElement('canvas'); c.width = Math.round(img.width * k); c.height = Math.round(img.height * k);
    const g = c.getContext('2d'); g.fillStyle = '#fff'; g.fillRect(0, 0, c.width, c.height); g.drawImage(img, 0, 0, c.width, c.height);
    return c.toDataURL('image/jpeg', 0.7);
  } catch { return ''; }
}

/** Upload one file for a unit. meta: { assetId, category, title, notes, woId, inspectionId }. Returns the record id. */
export async function addDoc(file, meta) {
  if (file.size > MAX_MB * 1e6 && !/^image\\//.test(file.type)) throw new Error(\`\${file.name} is \${(file.size / 1e6).toFixed(1)} MB. The limit is \${MAX_MB} MB per file — attach a smaller copy or a PDF.\`);
  const f = await prepFileBig(file);
  const isPhoto = /^image\\//.test(f.type);
  const b64 = String(f.data).split(',')[1] || '', n = Math.max(1, Math.ceil(b64.length / PART));
  const rec = { assetId: meta.assetId, category: meta.category || (isPhoto ? 'Photo' : 'Other'), title: meta.title || f.name.replace(/\\.[^.]+$/, ''), name: f.name, type: f.type, size: f.size, parts: n,
    thumb: isPhoto ? await thumbOf(f.data) : '', notes: meta.notes || '', woId: meta.woId || '', inspectionId: meta.inspectionId || '', addedAt: new Date().toISOString(), addedBy: store.user?.name || store.user?.email || '' };
  const id = 'D' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  // Parts first, then the record, so the list never shows a file that isn't fully saved.
  for (let p = 0; p < n; p++) {
    const part = { docId: id, part: p, data: b64.slice(p * PART, (p + 1) * PART) };
    if (store.demo) await idb('readwrite', s => s.put({ id: \`\${id}|\${p}\`, ...part }));
    else await store.set('mheFiles', \`\${id}__\${p}\`, part);
  }
  await store.set('mheDocs', id, rec);
  return id;
}
// prepFile (Safety Incident attachments) limits a non-photo file to one Firestore document; here files are split into
// parts, so only photos go through it (resized), and other files are read as they are.
async function prepFileBig(file) {
  if (/^image\\/(jpeg|png|webp|bmp|gif)$/i.test(file.type)) return prepFile(file);
  const data = await new Promise((res, rej) => { const r = new FileReader(); r.onload = () => res(r.result); r.onerror = () => rej(r.error); r.readAsDataURL(file); });
  return { name: file.name, type: file.type || 'application/octet-stream', size: file.size, data };
}
/** The file's bytes as a Blob. */
export async function docBlob(rec) {
  let s = '';
  for (let p = 0; p < (rec.parts || 1); p++) {
    const d = store.demo ? await idb('readonly', o => o.get(\`\${rec.id}|\${p}\`)) : await store.get('mheFiles', \`\${rec.id}__\${p}\`);
    if (!d) throw new Error(\`Part of \${rec.name} is missing — upload it again.\`);
    s += d.data;
  }
  return new Blob([dataBytes('data:;base64,' + s)], { type: rec.type || 'application/octet-stream' });
}
/** Open a photo or PDF in a new tab; other files download. */
export async function openDoc(rec) {
  const blob = await docBlob(rec);
  if (/^image\\/|pdf$/i.test(rec.type || '')) { const u = URL.createObjectURL(blob); const w = window.open(u, '_blank'); if (!w) downloadBlob(rec.name, blob); setTimeout(() => URL.revokeObjectURL(u), 60000); }
  else downloadBlob(rec.name, blob);
}
export async function saveDocBlob(rec) { downloadBlob(rec.name, await docBlob(rec)); }
/** Remove a file and its parts (managers; asked to confirm first). */
export async function removeDoc(rec) {
  for (let p = 0; p < (rec.parts || 1); p++) {
    if (store.demo) await idb('readwrite', o => o.delete(\`\${rec.id}|\${p}\`));
    else await store.remove('mheFiles', \`\${rec.id}__\${p}\`).catch(() => {});
  }
  await store.remove('mheDocs', rec.id);
}
export const fmtSize = n => (n >= 1e6 ? \`\${(n / 1e6).toFixed(1)} MB\` : \`\${Math.max(1, Math.round(n / 1e3))} KB\`);`]);

