ATL_SRC.push(['@atl/views/empids.js', 0, `// Data ▸ Employees ▸ "Sync with HR file": reads the HR system's Employee Information export (.csv) and makes the
// roster match it — HR Employee Ids, the spelling of each name (roster name and labor name, with every log entry under
// the old name moved to the new one), duplicate roster / labor records merged, and people missing from the roster
// added. Everything is shown first; nothing is saved until Save.
import { store } from '@atl/store.js';
import { esc, norm, toast } from '@atl/util.js';
import { nameScore } from '@atl/hrpdf.js';

/** Minimal CSV parser (quoted fields, commas and quotes inside quotes). */
function parseCSV(text) {
  const rows = []; let row = [], cell = '', q = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) { if (c === '"' && text[i + 1] === '"') { cell += '"'; i++; } else if (c === '"') q = false; else cell += c; }
    else if (c === '"') q = true;
    else if (c === ',') { row.push(cell); cell = ''; }
    else if (c === '\\n' || c === '\\r') { if (c === '\\r' && text[i + 1] === '\\n') i++; row.push(cell); rows.push(row); row = []; cell = ''; }
    else cell += c;
  }
  if (cell || row.length) { row.push(cell); rows.push(row); }
  return rows;
}

/** HR spelling, tidied: single spaces, no spaces around hyphens ("Aguilera- Avila" → "Aguilera-Avila"). */
const tidy = s => String(s || '').replace(/\\s*-\\s*/g, '-').replace(/\\s+/g, ' ').trim();

/** [{ id, first, last, status, full }] from the export — the table starts at the "Employee Id" header row. */
function readExport(text) {
  const rows = parseCSV(text), h = rows.findIndex(r => r.some(c => norm(c) === 'EMPLOYEE ID'));
  if (h < 0) throw new Error('This file has no "Employee Id" column — use the HR system\\'s Employee Information export.');
  const col = name => rows[h].findIndex(c => norm(c) === name);
  const [ci, cf, cl, cs] = ['EMPLOYEE ID', 'FIRST NAME', 'LAST NAME', 'EMPLOYEE STATUS'].map(col);
  if (cf < 0 || cl < 0) throw new Error('The export needs "First Name" and "Last Name" columns.');
  return rows.slice(h + 1).filter(r => (r[ci] || '').trim()).map(r => {
    const first = tidy(r[cf]), last = tidy(r[cl]);
    return { id: r[ci].trim(), first, last, full: \`\${first} \${last}\`.trim(), status: cs >= 0 ? (r[cs] || '').trim() : '' };
  });
}

// Log fields that hold an employee's name. Roster names (UPPER CASE) and labor names (Title Case) are kept separately.
const ROSTER_REFS = [['attendance', 'employee'], ['discipline', 'employee'], ['recognition', 'recipient'], ['damage', 'operator'], ['otif', 'responsible']];
const LABOR_REFS = [['labor', 'employee'], ['opmoves', 'operator']];
const NEEDS = ['employees', ...new Set([...ROSTER_REFS, ...LABOR_REFS].map(([c]) => c))];
/** OTIF "Responsible Party" can name several people ("JOHN DOE / JANE DOE"): replace whole-name matches inside it. */
const swapIn = (v, from, to) => String(v).replace(new RegExp(\`(^|[^A-Za-z])\${from.replace(/[.*+?^\${}()|[\\]\\\\]/g, '\\\\$&')}(?=$|[^A-Za-z])\`, 'gi'), (m, pre) => pre + to);
const refsTo = (refs, name) => refs.flatMap(([coll, key]) => store.rows(coll).filter(r => r[key] && (key === 'responsible' ? swapIn(r[key], name, '\\u0000') !== String(r[key]) : norm(r[key]) === norm(name))).map(r => [coll, key, r]));

/** Work out every change the HR file implies. */
function plan(people) {
  const emps = store.rows('employees'), used = new Set();
  const out = { renames: [], merges: [], ids: [], adds: [], ambiguous: [], notInFile: [] };
  for (const p of people) {
    const scored = emps.filter(e => !used.has(e.id)).map(e => [e, Math.max(nameScore(p.full, e.name || ''), nameScore(p.full, e.laborName || ''))]).filter(([, s]) => s > 0).sort((a, b) => b[1] - a[1]);
    const top = scored.filter(([, s]) => s === scored[0]?.[1]).map(([e]) => e);
    let e = null, merge = null;
    if (top.length === 1) e = top[0];
    else if (top.length === 2) {
      // A roster-only record and a labor-only record for the same person (their link was misspelled): merge them.
      const ros = top.find(x => x.name && !x.laborName), lab = top.find(x => !x.name && x.laborName);
      if (ros && lab) { e = ros; merge = lab; }
    }
    if (!e) { (scored.length ? out.ambiguous : out.adds).push({ p, options: top }); continue; }
    used.add(e.id); if (merge) used.add(merge.id);
    const rosterName = p.full.toUpperCase(), laborName = p.full;
    const curLabor = merge ? merge.laborName : e.laborName;
    if (merge) out.merges.push({ p, e, lab: merge });
    if (e.name && e.name !== rosterName) out.renames.push({ p, e, kind: 'roster', from: e.name, to: rosterName, refs: refsTo(ROSTER_REFS, e.name) });
    if (curLabor && curLabor !== laborName) out.renames.push({ p, e, kind: 'labor', from: curLabor, to: laborName, refs: refsTo(LABOR_REFS, curLabor) });
    const curId = String(e.hrId || merge?.hrId || '').trim();
    if (curId !== p.id) out.ids.push({ p, e, from: curId });
  }
  // Active on the roster but not in the HR file (the export leaves out terminated employees) — listed, not changed.
  out.notInFile = emps.filter(e => e.name && norm(e.rosterStatus) === 'ACTIVE' && !used.has(e.id));
  return out;
}

async function apply(pl, addMissing) {
  let n = 0;
  for (const m of pl.merges) {
    // Copy the labor-only record's details onto the roster record, then remove the duplicate.
    const lab = m.lab, keep = {};
    for (const k of ['laborName', 'payType', 'defaultBuilding', 'laborActive', 'hrId', 'manager', 'director', 'shiftStart']) if (lab[k] && !m.e[k]) keep[k] = lab[k];
    keep.notes = [m.e.notes, lab.notes && !/^Roster link not found/i.test(lab.notes) ? lab.notes : ''].filter(Boolean).join(' · ');
    await store.update('employees', m.e.id, keep); await store.remove('employees', lab.id); n++;
  }
  for (const r of pl.renames) {
    for (const [coll, key, row] of r.refs) await store.update(coll, row.id, { [key]: key === 'responsible' ? swapIn(row[key], r.from, r.to) : r.to });
    await store.update('employees', r.e.id, r.kind === 'roster' ? { name: r.to } : { laborName: r.to }); n++;
  }
  for (const x of pl.ids) { await store.update('employees', x.e.id, { hrId: x.p.id }); n++; }
  if (addMissing) for (const a of pl.adds) {
    await store.add('employees', { name: a.p.full.toUpperCase(), rosterStatus: 'Active', laborName: a.p.full, laborActive: 'Y', payType: 'Hourly', laborCategory: 'Operator', hrId: a.p.id, shiftStart: '07:50', notes: 'Added from the HR Employee Information export — set Home Facility.' }); n++;
  }
  return n;
}

/** Open the file picker, show what the HR file will change, and apply it on Save. */
export function importEmployeeIds(rerender) {
  const pick = document.createElement('input');
  pick.type = 'file'; pick.accept = '.csv,text/csv';
  pick.addEventListener('change', async () => {
    const file = pick.files[0]; if (!file) return;
    let pl;
    try { await store.need(NEEDS); pl = plan(readExport(await file.text())); } catch (err) { toast(err.message, 'bad'); return; }
    const sec = (title, items, fmt, note = '') => items.length ? \`<h4>\${title} <span class="muted">(\${items.length})</span></h4>\${note ? \`<p class="muted small">\${note}</p>\` : ''}<ul class="ids-list">\${items.map(fmt).join('')}</ul>\` : '';
    const refsTxt = refs => { const by = {}; for (const [c] of refs) by[c] = (by[c] || 0) + 1; return Object.entries(by).map(([c, k]) => \`\${k} \${c}\`).join(', '); };
    const el = document.createElement('div');
    el.className = 'modal-back ids-back';
    el.innerHTML = \`<div class="modal ids-pop" role="dialog" aria-modal="true" aria-labelledby="ids-title">
      <div class="modal-head"><h2 id="ids-title">Sync employees with \${esc(file.name)}</h2><button type="button" class="icon-btn" data-close aria-label="Close">✕</button></div>
      <p class="muted small">The HR file is the reference: names are spelled as HR has them. Matched to the roster by name. Nothing is saved until you press Save.</p>
      \${sec('Name corrections', pl.renames, r => \`<li><b>\${esc(r.from)}</b> → <b>\${esc(r.to)}</b> <span class="muted">(\${r.kind} name\${r.refs.length ? \`; \${refsTxt(r.refs)} entr\${r.refs.length === 1 ? 'y' : 'ies'} moved to the new name\` : ''})</span></li>\`, 'Every log entry under the old name is moved to the new one, so the person\\'s history stays together.')}
      \${sec('Duplicate records merged', pl.merges, m => \`<li><b>\${esc(m.e.name)}</b> + labor record “\${esc(m.lab.laborName)}” → one record</li>\`, 'Roster and labor records for the same person that were not linked (misspelled link).')}
      \${sec('HR Employee Ids', pl.ids, x => \`<li><b>\${esc(x.p.full)}</b>: \${x.from ? \`\${esc(x.from)} → \` : ''}\${esc(x.p.id)}</li>\`)}
      \${pl.adds.length ? \`<h4>In the HR file but not on the roster <span class="muted">(\${pl.adds.length})</span></h4><label class="ids-add"><input type="checkbox" data-add checked> Add \${pl.adds.length === 1 ? 'them' : 'them'} to the roster as Active (set their Home Facility afterwards)</label><ul class="ids-list">\${pl.adds.map(a => \`<li>\${esc(a.p.full)} · \${esc(a.p.id)}</li>\`).join('')}</ul>\` : ''}
      \${sec('Could not tell which employee — not changed', pl.ambiguous, a => \`<li>\${esc(a.p.full)} · \${esc(a.p.id)} <span class="muted">(\${a.options.map(o => esc(o.name || o.laborName)).join(' / ')})</span></li>\`)}
      \${sec('Active on the roster but not in the HR file — not changed', pl.notInFile, e => \`<li>\${esc(e.name)}</li>\`, 'The HR export leaves out terminated employees. If any of these have left, set them to “Not on Current Roster”.')}
      \${pl.renames.length + pl.merges.length + pl.ids.length + pl.adds.length ? '' : '<p><b>Everything already matches the HR file.</b></p>'}
      <div class="modal-foot"><span></span><div><button type="button" class="btn ghost" data-close>Cancel</button>
        <button type="button" class="btn primary" data-save \${pl.renames.length + pl.merges.length + pl.ids.length + pl.adds.length ? '' : 'disabled'}>Save changes</button></div></div></div>\`;
    document.body.appendChild(el);
    const close = () => el.remove();
    el.addEventListener('click', e => { if (e.target === el || e.target.closest('[data-close]')) close(); });
    el.addEventListener('keydown', e => { if (e.key === 'Escape') close(); });
    el.querySelector('[data-save]').addEventListener('click', async e => {
      e.target.disabled = true; e.target.textContent = 'Saving…';
      try { const n = await apply(pl, !!el.querySelector('[data-add]')?.checked); close(); rerender?.(); toast(\`Employees synced with the HR file — \${n} change\${n === 1 ? '' : 's'} saved\`); }
      catch (err) { console.error(err); toast(\`Stopped part-way: \${err.message}\`, 'bad'); close(); rerender?.(); }
    });
    el.querySelector('[data-save]').focus();
  });
  pick.click();
}`]);

// ===================== views/importer.js =====================
ATL_SRC.push(['@atl/views/importer.js', 0, `// One-time (or repeatable) import of the "Atlanta Division - Rail OTIF KPI Dashboard.xlsx" workbook.
// Runs entirely in the browser: the file is parsed with SheetJS and written to the database.
import { store, withDefaults, withRailDefaults, REF_PREFIX } from '@atl/store.js';
import { esc, excelDate, excelTime, norm, toast, $ } from '@atl/util.js';
import { page, section, table, ask } from '@atl/ui.js';
import { isCustomer, canonicalCustomer } from '@atl/throughput.js';
import { COLLS as MHE_COLLS, readRegister, isRegisterBook, planImport, applyImport, planTableHtml } from '@atl/mhe.js';

const SHEETJS = 'https://cdn.sheetjs.com/xlsx-0.20.3/package/xlsx.mjs';
let parsed = null, busy = false, progress = '', mhe = null; // mhe = the MHE Fleet Register workbook, read

const s = v => (v == null ? '' : String(v).trim());
const n = v => (v === '' || v == null || isNaN(+v) ? '' : +v);
const pad = i => String(i).padStart(4, '0');

export async function parseWorkbook(buf) {
  const XLSX = await import(SHEETJS);
  const wb = XLSX.read(buf, { type: 'array' });
  const sheet = name => wb.Sheets[name];
  const rows = (name, start) => {
    const ws = sheet(name); if (!ws) return [];
    return XLSX.utils.sheet_to_json(ws, { header: 'A', raw: true, defval: '' }).map(r => ({ ...r, _row: r.__rowNum__ + 1 })).filter(r => r._row >= start);
  };
  const cell = (name, ref) => sheet(name)?.[ref]?.v ?? '';
  const refId = (r, prefix) => (s(r.B).startsWith(prefix + '-') ? s(r.B) : \`\${prefix}-\${pad(r._row - 6)}\`);
  const out = { _sheets: wb.SheetNames };

  out.otif = rows('OTIF Log', 7).filter(r => s(r.C)).map(r => ({
    id: refId(r, 'OTIF'), date: excelDate(r.C), facility: s(r.E), customer: s(r.F), type: s(r.G), category: s(r.H), responsible: s(r.I),
    description: s(r.J), rootCause: s(r.L), corrective: s(r.M), capa: s(r.N), status: s(r.O), cost: n(r.P),
  }));
  out.attendance = rows('Attendance Log', 7).filter(r => s(r.D)).map(r => ({
    id: refId(r, 'ATT'), employee: s(r.C), date: excelDate(r.D), schedStart: excelTime(r.F), arrival: excelTime(r.G), leftEarly: excelTime(r.H),
    excused: s(r.K), reason: s(r.L), recordedBy: s(r.M), cleanupNote: s(r.P),
  }));
  out.damage = rows('Damage Log', 7).filter(r => s(r.C)).map(r => ({
    id: refId(r, 'DMG'), date: excelDate(r.C), facility: s(r.E), customer: s(r.F), stage: s(r.G), damageType: s(r.H), cause: s(r.I),
    responsible: s(r.J), product: s(r.K), qty: n(r.L), unit: s(r.M), value: n(r.N), operator: s(r.O), recordedBy: s(r.P),
    photos: s(r.Q), claimNo: s(r.R), claimStatus: s(r.S), notes: s(r.T),
  }));
  out.labor = rows('Labor', 7).filter(r => s(r.B) && s(r.E)).map(r => ({
    // "Employee" / "Clerical" are the workbook's old names for Hourly (the app renamed them), so they match app rows.
    weekEnding: excelDate(r.B), building: s(r.D), employee: s(r.E), payType: ['EMPLOYEE', 'CLERICAL'].includes(norm(s(r.F))) ? 'Hourly' : s(r.F), reg: n(r.G), ot: n(r.H),
  }));
  out.throughput = rows('Customer Throughput', 7).filter(r => s(r.B) && s(r.E)).map(r => ({
    weekEnding: excelDate(r.B), building: s(r.D), customer: s(r.E), unit: s(r.F), inbound: n(r.G), outbound: n(r.H),
  }));
  out.recognition = rows('Recognition', 7).filter(r => s(r.B) && s(r.D)).map(r => ({
    month: excelDate(r.B).slice(0, 8) + '01', award: s(r.C), recipient: s(r.D), notes: s(r.E),
  }));
  out.discipline = rows('Disciplinary Log', 7).filter(r => s(r.C) && s(r.D)).map(r => ({
    id: refId(r, 'DSC'), date: excelDate(r.C), employee: s(r.D), category: s(r.F), action: s(r.G), description: s(r.H),
    issuedBy: s(r.I), signed: s(r.J), notes: s(r.N),
  }));

  // Employees: roster (B–F) merged with labor-name setup (G–N) via "Attendance Roster Name" (H).
  const emp = new Map();
  for (const r of rows('Employees', 6)) if (s(r.B)) emp.set(norm(r.B), { name: s(r.B).toUpperCase(), rosterStatus: s(r.C), homeFacility: s(r.D), notes: s(r.E), shiftStart: excelTime(r.F) });
  for (const r of rows('Employees', 6)) {
    if (!s(r.G)) continue;
    const labor = { laborName: s(r.G), payType: !s(r.I) || norm(s(r.I)) === 'EMPLOYEE' ? 'Hourly' : s(r.I), defaultBuilding: s(r.J), laborActive: s(r.K) || 'Y', hrId: s(r.N) };
    const key = norm(r.H);
    if (key && emp.has(key) && !emp.get(key).laborName) Object.assign(emp.get(key), labor);
    else emp.set('labor:' + norm(r.G), { name: '', rosterStatus: '', homeFacility: s(r.J), notes: s(r.H) ? \`Roster link not found: \${s(r.H)}\` : '', ...labor });
  }
  out.employees = [...emp.values()];

  out.monthly = rows('Monthly Inputs', 7).filter(r => typeof r.B === 'number').map(r => {
    const iso = excelDate(r.B);
    return { id: iso.slice(0, 7), month: iso.slice(0, 8) + '01', loads6049: n(r.C), hc6049: n(r.D), loads6021: n(r.E), hc6021: n(r.F), notes: s(r.J) };
  }).map(m => Object.fromEntries(Object.entries(m).filter(([, v]) => v !== '')));

  // Settings
  const S = 'Settings', col = (letter, from = 6, to = 120) => {
    const vals = [];
    for (let i = from; i <= to; i++) { const v = s(cell(S, letter + i)); if (v) vals.push(v); else if (vals.length && !s(cell(S, letter + (i + 1)))) break; }
    return vals;
  };
  const incidentTypes = [];
  for (let i = 14; i < 19; i++) { const nm = s(cell(S, 'B' + i)); if (nm) incidentTypes.push({ name: nm, counts: /^y/i.test(s(cell(S, 'C' + i))), definition: s(cell(S, 'D' + i)) }); }
  const throughputCustomers = [];
  for (let i = 8; i < 47; i++) { const nm = s(cell(S, 'AD' + i)); if (nm) throughputCustomers.push({ name: nm, building: s(cell(S, 'AE' + i)), active: s(cell(S, 'AG' + i)) || 'Y' }); }
  const hrCounters = [];
  for (let i = 6; i <= 20; i++) { const c = s(cell(S, 'AK' + i)); if (c) hrCounters.push({ counter: c, countsAs: s(cell(S, 'AL' + i)) || 'Ignore' }); }
  const shift = cell(S, 'C7');
  out.settings = {
    reportingYear: n(cell(S, 'C6')) || new Date().getFullYear(),
    defaultShiftStart: typeof shift === 'number' ? excelTime(shift) : '07:50',
    orderAccuracyTarget: n(cell(S, 'C8')) || 0.99, attendanceTarget: n(cell(S, 'C9')) || 0.95,
    disciplineMonths: n(cell(S, 'C10')) || 12, salariedHours: n(cell(S, 'C38')) || 40,
    damageTarget6049: n(cell(S, 'C25')) === '' ? null : n(cell(S, 'C25')), damageTarget6021: n(cell(S, 'C26')) === '' ? null : n(cell(S, 'C26')),
    incidentTypes, throughputCustomers, hrCounters,
    lists: {
      incidentCategories: col('F'), customers: col('G'), facilities: col('H'), supervisors: col('I'), incidentStatus: col('J'),
      awardTypes: col('L'), rosterStatus: col('M'), damageStage: col('N'), damageType: col('O'), damageCause: col('P'),
      damageResponsible: col('Q'), damageUnit: col('R'), claimStatus: col('S'), disciplineCategories: col('U'), disciplineActions: col('V'),
    },
  };
  for (const [k, v] of Object.entries(out.settings.lists)) if (!v.length) delete out.settings.lists[k];

  // Rail
  const R = 'Rail Settings', railCustomers = [];
  for (let i = 6; i < 30; i++) {
    const nm = s(cell(R, 'B' + i)); if (!nm) break;
    railCustomers.push({ name: nm, tab: s(cell(R, 'C' + i)) || nm, freeDays: n(cell(R, 'D' + i)) || 5, rate: n(cell(R, 'E' + i)) || 40, building: s(cell(R, 'F' + i)) });
  }
  out.rail = { openCarWindowDays: n(cell(R, 'H11')) || 30, customers: railCustomers.map(({ tab, ...c }) => c) };
  // Column R ("Data Check") is a formula; anything else typed over it is a note worth keeping.
  const CHECKS = /^(Rail car # missing|CP date missing|CP date out of range|Release date not a date|Release before CP date|No release date)/;
  const railNotes = r => [s(r.K), s(r.R) && !CHECKS.test(s(r.R)) ? s(r.R) : ''].filter(Boolean).join(' · ');
  out.railcars = railCustomers.flatMap(c => rows(c.tab, 17).filter(r => ['B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'].some(k => s(r[k]))).map(r => ({
    customer: c.name, car: s(r.B).toUpperCase(), cpDate: excelDate(r.C), cpTime: excelTime(r.D), orderedDate: excelDate(r.E), orderedTime: excelTime(r.F),
    placedDate: excelDate(r.G), placedTime: excelTime(r.H), releasedDate: excelDate(r.I), releasedTime: excelTime(r.J), notes: railNotes(r), waive: s(r.L).toUpperCase(),
  })));
  return out;
}

// Which sheet each collection comes from: a collection whose sheet isn't in the file is left as it is.
const SHEET_OF = { employees: 'Employees', otif: 'OTIF Log', attendance: 'Attendance Log', damage: 'Damage Log', labor: 'Labor', throughput: 'Customer Throughput', recognition: 'Recognition', discipline: 'Disciplinary Log', monthly: 'Monthly Inputs', railcars: 'Rail Settings' };
const inFile = (data, c) => !data._sheets || data._sheets.includes(SHEET_OF[c]);
const COLLS = ['employees', 'otif', 'attendance', 'damage', 'labor', 'throughput', 'recognition', 'discipline', 'monthly', 'railcars'];

// ---------- Update from the workbook (never wipes) ----------
// Each workbook row is matched to the app's row by its ID (OTIF-0042 …) or, for rows without one, by what it is
// (week + building + employee, week + building + customer …). Matched rows get the workbook's values (fields the
// workbook doesn't have, e.g. Weekly Entry loads or a rail Turn, are kept); unmatched rows are added; rows only in
// the app are kept. Nothing is deleted, and no other part of the app (MHE Fleet, safety, scorecards …) is touched.
const LABEL = { employees: 'Employees', otif: 'OTIF Log', attendance: 'Attendance Log', damage: 'Damage Log', labor: 'Labor', throughput: 'Customer Throughput', recognition: 'Recognition', discipline: 'Disciplinary Log', monthly: 'Monthly Inputs', railcars: 'Rail cars' };
const ID_COLLS = new Set(['otif', 'attendance', 'damage', 'discipline', 'monthly']);
const KEY_OF = {
  employees: r => (s(r.name) ? norm(r.name) : 'labor:' + norm(r.laborName)),
  // One row per person per week per building — pay type is left out so a renamed pay type can't add a second copy.
  labor: r => [r.weekEnding, String(r.building), norm(r.employee)].join('|'),
  recognition: r => [r.month, norm(r.award), norm(r.recipient)].join('|'),
  railcars: r => [norm(r.customer), norm(r.car), r.cpDate].join('|'),
};
const sameRow = (have, x) => Object.keys(x).every(k => k === 'id' || String(have[k] ?? '') === String(x[k] ?? ''));

/** What loading the workbook would do, per collection: rows to add / update, unchanged, kept (app only), and rows
 *  skipped because the app has a different entry under the same ID. Needs the collections loaded. */
export function planWorkbook(data) {
  const customers = [...(store.settings?.throughputCustomers || []), ...(data.settings?.throughputCustomers || [])];
  const who = name => customers.find(c => isCustomer(c, name))?.name || name;
  const keyOf = { ...KEY_OF, throughput: r => [r.weekEnding, String(r.building), norm(who(r.customer))].join('|') };
  return COLLS.filter(c => inFile(data, c)).map(coll => {
    // Labor rows for people marked "Leave Off Labor Hours" (Employees) are not brought in.
    const off = new Set(store.rows('employees').filter(e => norm(e.laborExclude) === 'Y').flatMap(e => [e.laborName, e.name]).filter(Boolean).map(norm));
    const docs = (data[coll] || []).filter(r => coll !== 'labor' || !off.has(norm(r.employee))), have = store.rows(coll);
    const add = [], upd = [], skip = [];
    let same = 0;
    if (ID_COLLS.has(coll)) {
      const byId = new Map(have.map(r => [r.id, r]));
      for (const x of docs) {
        const h = byId.get(x.id);
        if (!h) add.push(x);
        // Same ID but a different date = a different entry made in the app: keep the app's, skip the workbook's.
        else if (coll !== 'monthly' && h.date && x.date && h.date !== x.date) skip.push(x);
        else if (sameRow(h, x)) same++;
        else upd.push({ ...x, id: h.id });
      }
      const ids = new Set(docs.map(x => x.id));
      return { coll, label: LABEL[coll], docs, add, upd, same, skip, kept: have.filter(r => !ids.has(r.id)).length };
    }
    // No IDs in the workbook: match by key; a key that repeats is matched in order (1st with 1st, 2nd with 2nd …).
    const k = keyOf[coll], seen = new Map(), nth = r => { const b = k(r), i = (seen.get(b) || 0) + 1; seen.set(b, i); return \`\${b}#\${i}\`; };
    const byKey = new Map(have.map(r => [nth(r), r])); seen.clear();
    const used = new Set();
    // Throughput rows are saved under the customer's set-up name ("Nexus" → "Nexus Circular", "IPG - iTape" → "IPG").
    const named = x => (coll === 'throughput' ? { ...x, customer: canonicalCustomer(x.customer, x.building, customers) } : x);
    for (const x of docs) {
      const key = nth(x), h = byKey.get(key);
      if (!h) { add.push(named(x)); continue; }
      used.add(h.id);
      const y = named(x);
      if (sameRow(h, y)) same++; else upd.push({ ...y, id: h.id });
    }
    return { coll, label: LABEL[coll], docs, add, upd, same, skip, kept: have.filter(r => !used.has(r.id)).length };
  });
}

/** Settings from the workbook: filled in full only when the app has none yet; otherwise only what the app is missing
 *  (new list items, incident types, customers, HR counters, rail customers) is added — nothing set in the app changes. */
function mergeSettings(cur, file) {
  if (!store.savedConfig?.settings) return withDefaults(file);
  const out = JSON.parse(JSON.stringify(cur));
  const addMissing = (list = [], extra = [], key) => [...list, ...extra.filter(e => !list.some(l => norm(key(l)) === norm(key(e))))];
  out.lists = { ...out.lists };
  for (const [k, v] of Object.entries(file.lists || {})) out.lists[k] = addMissing(out.lists[k] || [], v, x => x);
  out.incidentTypes = addMissing(out.incidentTypes, file.incidentTypes, t => t.name);
  out.throughputCustomers = [...(out.throughputCustomers || []), ...(file.throughputCustomers || []).filter(c => !(out.throughputCustomers || []).some(a => isCustomer(a, c.name)))];
  out.hrCounters = addMissing(out.hrCounters, file.hrCounters, c => c.counter);
  return out;
}
function mergeRail(cur, file) {
  if (!store.savedConfig?.rail) return withRailDefaults(file);
  const out = JSON.parse(JSON.stringify(cur));
  out.customers = [...(out.customers || []), ...(file.customers || []).filter(c => !(out.customers || []).some(a => norm(a.name) === norm(c.name)))];
  return out;
}

export async function writeImport(data, onStep = () => {}) {
  await store.need(COLLS.filter(c => inFile(data, c)));
  // Matching needs the app's current rows: if any couldn't be read, stop (rows would be added twice).
  const unread = COLLS.filter(c => inFile(data, c) && store.readErrors.has(c));
  if (unread.length) throw new Error(\`Couldn't read the app's current \${unread.join(', ')} (permission), so nothing was imported. Sign out and back in, or check the Firestore rules, then try again.\`);
  const plan = planWorkbook(data);
  if (!data._sheets || data._sheets.includes('Settings')) await store.saveConfig('settings', mergeSettings(store.settings, data.settings));
  if (!data._sheets || data._sheets.includes('Rail Settings')) await store.saveConfig('rail', mergeRail(store.rail, data.rail));
  for (const p of plan) {
    const have = new Map(store.rows(p.coll).map(r => [r.id, r]));
    const docs = [...p.add, ...p.upd.map(x => ({ ...have.get(x.id), ...x }))];
    if (!docs.length) continue;
    onStep(\`\${p.label}: writing \${docs.length}…\`);
    for (let i = 0; i < docs.length; i += 400) await store.writeMany(p.coll, docs.slice(i, i + 400));
    // Numbered entries (OTIF-0042 …): the next one made in the app carries on after the highest number.
    const prefix = REF_PREFIX[p.coll];
    if (prefix && p.add.length) {
      const top = Math.max(0, ...store.rows(p.coll).concat(p.add).map(d => (String(d.id).startsWith(prefix + '-') ? parseInt(d.id.slice(prefix.length + 1), 10) || 0 : 0)));
      const cur = (await store.get('counters', p.coll))?.next || 0;
      if (top + 1 > cur) await store.set('counters', p.coll, { next: top + 1 });
    }
  }
  onStep('Done');
  return plan;
}

const workbookPlanHtml = plan => \`<div class="table-wrap"><table class="grid"><thead><tr><th>Sheet</th><th class="num">Rows in file</th><th class="num">New</th><th class="num">Updated</th><th class="num">Unchanged</th><th class="num">In the app only (kept)</th>\${plan.some(p => p.skip.length) ? '<th class="num">Skipped (ID used by an app entry)</th>' : ''}</tr></thead><tbody>
  \${plan.map(p => \`<tr><td>\${p.label}</td><td class="num">\${p.docs.length}</td><td class="num"><b>\${p.add.length}</b></td><td class="num"><b>\${p.upd.length}</b></td><td class="num">\${p.same}</td><td class="num">\${p.kept}</td>\${plan.some(q => q.skip.length) ? \`<td class="num">\${p.skip.length}</td>\` : ''}</tr>\`).join('')}</tbody></table></div>\`;

// ---------- Demo Mode backup → shared database ----------
// The backup is the demo store as is: { collection: { id: data } }, config docs under "config".
const BACKUP_SKIP = ['users', 'counters'];
let backup = null, backupMsg = '';
async function loadBackup(data, say) {
  for (const [name, doc] of Object.entries(data.config || {})) await store.saveConfig(name, doc);
  for (const [coll, docs] of Object.entries(data)) {
    if (coll === 'config' || BACKUP_SKIP.includes(coll)) continue;
    const list = Object.entries(docs).map(([id, d]) => ({ ...d, id }));
    // Batches under ~8 MB (attachments are large) and 400 entries.
    let chunk = [], size = 0, done = 0;
    const flush = async () => { if (!chunk.length) return; await store.writeMany(coll, chunk); done += chunk.length; say(\`\${coll}: \${done} / \${list.length}\`); chunk = []; size = 0; };
    for (const d of list) {
      const n = JSON.stringify(d).length;
      if (chunk.length && (size + n > 8e6 || chunk.length >= 400)) await flush();
      chunk.push(d); size += n;
    }
    await flush();
    // Numbered entries (OTIF-0042 …) carry on after the highest number.
    const prefix = REF_PREFIX[coll];
    if (prefix) {
      const top = Math.max(0, ...list.map(d => (d.id.startsWith(prefix + '-') ? parseInt(d.id.slice(prefix.length + 1), 10) || 0 : 0)));
      await store.set('counters', coll, { next: top + 1 });
    }
  }
}

// Test hook: window.atlImport(arrayBuffer)
window.atlImport = async buf => { const d = await parseWorkbook(buf); const plan = await writeImport(d); return Object.fromEntries(plan.map(p => [p.coll, { file: p.docs.length, new: p.add.length, updated: p.upd.length, same: p.same, kept: p.kept, skipped: p.skip.length }])); };

export default {
  needs: () => [],
  render() {
    if (!store.can('admin')) return page('Import from Excel', 'Admin access is needed.');
    const kpiPlan = parsed ? planWorkbook(parsed) : null;
    const preview = parsed ? section('Ready to update — Rail OTIF KPI Dashboard', \`<p><b>\${esc(parsed._file || '')}</b> is the Rail OTIF KPI Dashboard workbook.</p>\${workbookPlanHtml(kpiPlan)}
      <p class="muted">Only the KPI data this workbook covers is written: new rows are added and changed rows are updated. Nothing is deleted — entries made in the app stay, and fields the workbook doesn't have (Weekly Entry loads, rail Turn …) are kept. MHE Fleet and everything else is not touched. Settings: \${store.savedConfig?.settings ? 'only list items, incident types, customers and HR counters the app doesn’t have yet are added; targets and lists set in the app stay as they are' : 'the app has none yet, so the workbook’s settings are used'}.</p>
       <button class="btn primary" data-go \${busy ? 'disabled' : ''}>\${busy ? 'Updating…' : 'Update KPI data from this file'}</button> <span class="muted">\${esc(progress)}</span>\`) : '';
    const bk = backup ? \`<p>Backup from \${esc(backup.exported ? new Date(backup.exported).toLocaleString() : 'demo mode')}: \${esc(Object.entries(backup.data).filter(([c]) => !BACKUP_SKIP.includes(c)).map(([c, d]) => \`\${c} \${Object.keys(d).length}\`).join(' · '))}</p>
      <p class="warnline">⚠ Loading it writes every entry, file and setting from the backup into the shared database (same IDs replace what is there).</p>
      <button class="btn primary" data-backup-go \${busy ? 'disabled' : ''}>\${busy ? 'Loading…' : 'Load this backup into the shared database'}</button> <span class="muted" data-backup-msg>\${esc(backupMsg)}</span>\` : \`<span class="muted">\${esc(backupMsg)}</span>\`;
    const mhePrev = mhe ? section('Ready to update — MHE Fleet Register', \`<p><b>\${esc(mhe.file)}</b> is the MHE Fleet Register workbook.</p>\${planTableHtml(planImport(mhe))}
      <button class="btn primary" data-mhe-go \${busy ? 'disabled' : ''}>\${busy ? 'Updating…' : 'Update MHE Fleet from this file'}</button> <a class="btn ghost" href="#/mhe">Open MHE Fleet</a> <span class="muted">\${esc(progress)}</span>\`) : '';
    return page('Import from Excel', 'Load a workbook (.xlsx): the Rail OTIF KPI Dashboard workbook or the MHE Fleet Register. The app recognizes which one it is and only writes the data that file covers. The file is read in your browser — nothing is uploaded anywhere except the rows written to the database.') +
      section('1 · Choose the workbook', \`<input type="file" accept=".xlsx,.xlsm" data-file> <span class="muted">\${esc(progress && !parsed && !mhe ? progress : '')}</span>\`) + preview + mhePrev +
      (store.demo ? '' : section('Load a backup (data from Demo Mode)', \`<p class="muted">The JSON backup made in Users &amp; Settings while the app ran in Demo Mode (data kept in one browser). Use it once, to move that data into the shared database.</p>
        <input type="file" accept=".json,application/json" data-backup> \${bk}\`));
  },
  after(root, p, rerender) {
    $('[data-file]', root)?.addEventListener('change', async e => {
      const f = e.target.files[0]; if (!f) return;
      progress = 'Reading workbook…'; parsed = null; mhe = null; rerender();
      try {
        const buf = await f.arrayBuffer(), XLSX = await import(SHEETJS), names = XLSX.read(buf, { type: 'array', bookSheets: true }).SheetNames;
        // The MHE Fleet Register only updates MHE Fleet; the OTIF workbook only the parts whose sheets it has.
        if (isRegisterBook({ Sheets: Object.fromEntries(names.map(n => [n, true])) })) { await store.need(MHE_COLLS); mhe = await readRegister(f); }
        else if (names.some(n => Object.values(SHEET_OF).includes(n) || n === 'Settings')) {
          const d = await parseWorkbook(buf); d._file = f.name;
          await store.need(COLLS.filter(c => inFile(d, c)));
          parsed = d;
        }
        else throw new Error('this isn\\'t a workbook the app knows (the Rail OTIF KPI Dashboard or the MHE Fleet Register). Nothing was imported.');
        progress = '';
      } catch (err) { console.error(err); progress = 'Could not read the file: ' + err.message; }
      rerender();
    });
    $('[data-backup]', root)?.addEventListener('change', async e => {
      const f = e.target.files[0]; if (!f) return;
      try {
        const j = JSON.parse(await f.text());
        if (j.app !== 'atl-ops' || !j.data) throw new Error('not an Atlanta Ops backup');
        backup = j; backupMsg = '';
      } catch (err) { backup = null; backupMsg = 'Could not read the backup: ' + err.message; }
      rerender();
    });
    $('[data-backup-go]', root)?.addEventListener('click', async () => {
      if (!await ask('Load every entry, file and setting from this backup into the shared database?', { ok: 'Load backup', danger: true })) return;
      busy = true; rerender();
      const say = m => { backupMsg = m; const el = $('[data-backup-msg]'); if (el) el.textContent = m; };
      try { await loadBackup(backup.data, say); toast('Backup loaded'); backup = null; say('Done'); }
      catch (err) { console.error(err); toast(err.message, 'bad'); say('Failed: ' + err.message); }
      busy = false; rerender();
    });
    $('[data-mhe-go]', root)?.addEventListener('click', async () => {
      busy = true; rerender();
      try {
        const plan = await applyImport(mhe, m => { progress = m; });
        toast(\`MHE Fleet updated: \${plan.reduce((t, x) => t + x.add.length, 0)} new, \${plan.reduce((t, x) => t + x.upd.length, 0)} updated rows. Nothing else was changed.\`);
        mhe = null; progress = '';
      } catch (err) { console.error(err); toast(err.message, 'bad'); progress = 'Failed: ' + err.message; }
      busy = false; rerender();
    });
    $('[data-go]', root)?.addEventListener('click', async () => {
      busy = true; rerender();
      try {
        const plan = await writeImport(parsed, m => { progress = m; const el = $('[data-go] + .muted'); if (el) el.textContent = m; });
        toast(\`KPI data updated: \${plan.reduce((t, x) => t + x.add.length, 0)} new, \${plan.reduce((t, x) => t + x.upd.length, 0)} updated rows. Nothing was deleted.\`);
        parsed = null; progress = '';
      }
      catch (err) { console.error(err); toast(err.message, 'bad'); progress = 'Failed: ' + err.message; }
      busy = false; rerender();
    });
  },
};`]);

