ATL_SRC.push(['@atl/views/labordups.js', 0, `// Data ▸ Labor ▸ "Remove duplicates": finds an employee entered more than once for the same week in the same
// building and deletes the extra rows. Rows with the same hours are removed automatically (one is kept); rows with
// different hours are listed so you pick the one to keep (or leave them). Nothing is deleted until you confirm.
// Pay type "Employee" and "Hourly" count as the same (Employee is the old name for Hourly).
import { store } from '@atl/store.js';
import { esc, norm, num, fmtDate, fmtNum, toast } from '@atl/util.js';

const same = (a, b) => Math.abs(num(a) - num(b)) < 0.01;
const ptype = r => (['EMPLOYEE', 'CLERICAL', ''].includes(norm(r.payType)) ? 'HOURLY' : norm(r.payType));

/** Groups of rows for one person, week and building. year = 'YYYY' or '' for every year. */
export function laborDuplicates(year) {
  const g = new Map();
  for (const r of store.rows('labor')) {
    if (year && !String(r.weekEnding || '').startsWith(year)) continue;
    const k = [r.weekEnding, String(r.building), norm(r.employee)].join('|');
    (g.get(k) || g.set(k, []).get(k)).push(r);
  }
  const exact = [], conflict = [];
  for (const rows of g.values()) {
    if (rows.length < 2) continue;
    // Keep the row already using the current pay-type names ("Hourly"), then the first by id, so the result is stable.
    rows.sort((a, b) => (norm(a.payType) === 'EMPLOYEE') - (norm(b.payType) === 'EMPLOYEE') || String(a.id).localeCompare(String(b.id)));
    const allSame = rows.every(r => same(r.reg, rows[0].reg) && same(r.ot, rows[0].ot) && ptype(r) === ptype(rows[0]));
    (allSame ? exact : conflict).push({ keep: rows[0], rows, extra: rows.slice(1) });
  }
  const byWeek = (a, b) => String(a.keep.weekEnding).localeCompare(String(b.keep.weekEnding)) || String(a.keep.employee).localeCompare(String(b.keep.employee));
  return { exact: exact.sort(byWeek), conflict: conflict.sort(byWeek) };
}

/** Delete rows by id in batches. */
async function removeRows(ids, say) {
  for (let i = 0; i < ids.length; i += 400) {
    await store.writeMany('labor', ids.slice(i, i + 400).map(id => ({ _delete: id })));
    say?.(Math.min(i + 400, ids.length));
  }
}

/** People on the labor log: [{ name, rows }] by name, every year. */
const people = () => {
  const m = new Map();
  for (const r of store.rows('labor')) { const k = norm(r.employee); if (!k) continue; (m.get(k) || m.set(k, { name: r.employee, rows: [] }).get(k)).rows.push(r); }
  return [...m.values()].sort((a, b) => a.name.localeCompare(b.name));
};

/** The review window: duplicate rows, and (section 2) every row for chosen people. */
export async function openLaborScrub(rerender) {
  await store.need(['labor', 'employees']);
  const picked = new Set();
  const years = [...new Set(store.rows('labor').map(r => String(r.weekEnding || '').slice(0, 4)).filter(y => /^\\d{4}$/.test(y)))].sort().reverse();
  let year = years.includes(String(new Date().getFullYear())) ? String(new Date().getFullYear()) : years[0] || '';
  const el = document.createElement('div');
  el.className = 'modal-back ids-back';
  document.body.appendChild(el);
  const close = () => el.remove();
  const hrs = r => \`\${fmtNum(num(r.reg), 1)} reg\${num(r.ot) ? \` + \${fmtNum(num(r.ot), 1)} OT\` : ''}\`;
  const draw = () => {
    const { exact, conflict } = laborDuplicates(year);
    const nExact = exact.reduce((a, g) => a + g.extra.length, 0);
    el.innerHTML = \`<div class="modal ids-pop ld-pop" role="dialog" aria-modal="true" aria-labelledby="ld-title">
      <div class="modal-head"><h2 id="ld-title">Clean up labor hours</h2><button type="button" class="icon-btn" data-close aria-label="Close">✕</button></div>
      <p class="muted small">Looks for the same employee entered more than once for the same week ending in the same building. One row is kept; the extra copies are deleted. Hours in the other building are a separate row and are not touched. Nothing is deleted until you press Delete.</p>
      <label class="inline small">Weeks in <select data-year aria-label="Which year to check">\${years.map(y => \`<option value="\${y}"\${y === year ? ' selected' : ''}>\${y}</option>\`).join('')}<option value=""\${year === '' ? ' selected' : ''}>All years</option></select></label>
      \${!exact.length && !conflict.length ? \`<p><b>No duplicates found\${year ? \` in \${year}\` : ''}.</b></p>\` : ''}
      \${exact.length ? \`<h4>Exact copies <span class="muted">(\${exact.length} people-weeks · \${nExact} extra row\${nExact === 1 ? '' : 's'} to delete)</span></h4>
        <p class="muted small">Same hours on every copy. One is kept, the rest are deleted.</p>
        <ul class="ids-list ld-list">\${exact.map(g => \`<li>\${fmtDate(g.keep.weekEnding)} · \${esc(g.keep.building)} · <b>\${esc(g.keep.employee)}</b> <span class="muted">\${hrs(g.keep)} × \${g.rows.length}</span></li>\`).join('')}</ul>\` : ''}
      \${conflict.length ? \`<h4>Different hours — pick the row to keep <span class="muted">(\${conflict.length})</span></h4>
        <p class="muted small">These copies don't agree. Pick the correct one and the others are deleted, or leave "Don't change" to keep them all.</p>
        \${conflict.map((g, i) => \`<div class="ld-conf"><div><b>\${esc(g.keep.employee)}</b> · week ending \${fmtDate(g.keep.weekEnding)} · \${esc(g.keep.building)}</div>
          <label><input type="radio" name="ld\${i}" value="" checked> Don't change</label>
          \${g.rows.map(r => \`<label><input type="radio" name="ld\${i}" value="\${esc(r.id)}"> Keep \${hrs(r)} <span class="muted">(\${esc(r.payType || '—')})</span></label>\`).join('')}</div>\`).join('')}\` : ''}
      <h4>Remove all hours for a person <span class="muted">(every year)</span></h4>
      <p class="muted small">Tick anyone whose hours shouldn't be on the labor log. Every one of their rows is deleted.</p>
      <div class="ld-people">\${people().map(p => \`<label><input type="checkbox" data-person="\${esc(norm(p.name))}"\${picked.has(norm(p.name)) ? ' checked' : ''}> \${esc(p.name)} <span class="muted">\${p.rows.length}</span></label>\`).join('')}</div>
      <label class="ids-add"><input type="checkbox" data-exclude checked> Also mark them “Leave Off Labor Hours” on Employees, so Weekly Entry and the Excel import don't add their hours back</label>
      <div class="modal-foot"><span class="muted small" data-msg></span><div><button type="button" class="btn ghost" data-close>Cancel</button>
        <button type="button" class="btn primary danger" data-go>Delete</button></div></div></div>\`;
    const go = el.querySelector('[data-go]'), msg = el.querySelector('[data-msg]');
    const personIds = () => people().filter(p => picked.has(norm(p.name))).flatMap(p => p.rows.map(r => r.id));
    const toDelete = () => {
      const ids = exact.flatMap(g => g.extra.map(r => r.id));
      conflict.forEach((g, i) => { const k = el.querySelector(\`input[name="ld\${i}"]:checked\`)?.value; if (k) ids.push(...g.rows.filter(r => r.id !== k).map(r => r.id)); });
      return [...new Set([...ids, ...personIds()])];
    };
    const count = () => { const n = toDelete().length; go.textContent = n ? \`Delete \${n} row\${n === 1 ? '' : 's'}\` : 'Delete'; go.disabled = !n; };
    el.querySelector('[data-year]').addEventListener('change', e => { year = e.target.value; draw(); });
    el.querySelectorAll('.ld-conf input').forEach(i => i.addEventListener('change', count));
    el.querySelectorAll('[data-person]').forEach(i => i.addEventListener('change', () => { if (i.checked) picked.add(i.dataset.person); else picked.delete(i.dataset.person); count(); }));
    count();
    go.addEventListener('click', async () => {
      const ids = toDelete(), who = people().filter(p => picked.has(norm(p.name))).map(p => p.name);
      const markOff = who.length && el.querySelector('[data-exclude]').checked;
      if (!ids.length || !confirm(\`Delete \${ids.length} labor row\${ids.length === 1 ? '' : 's'}?\${who.length ? \`\\n\\nThis includes every row for \${who.join(', ')}.\` : ''}\\n\\nThis can't be undone.\`)) return;
      go.disabled = true; go.textContent = 'Deleting…';
      try {
        await removeRows(ids, n => { msg.textContent = \`\${n} / \${ids.length} deleted…\`; });
        let marked = 0;
        if (markOff) for (const e of store.rows('employees')) if (picked.has(norm(e.laborName)) || picked.has(norm(e.name))) { await store.update('employees', e.id, { laborExclude: 'Y' }); marked++; }
        close(); rerender?.(); toast(\`Deleted \${ids.length} labor row\${ids.length === 1 ? '' : 's'}\${markOff ? \` · \${marked} employee record\${marked === 1 ? '' : 's'} marked “Leave Off Labor Hours”\` : ''}\`);
      } catch (err) { console.error(err); toast(\`Stopped part-way: \${err.message}\`, 'bad'); close(); rerender?.(); }
    });
  };
  el.addEventListener('click', e => { if (e.target === el || e.target.closest('[data-close]')) close(); });
  el.addEventListener('keydown', e => { if (e.key === 'Escape') close(); });
  draw();
}`]);

