ATL_SRC.push(['@atl/views/mhereports.js', 0, `// MHE Fleet ▸ Reports: fleet by warehouse and type, maintenance cost by month and by warehouse, downtime, repair
// frequency, inspection compliance, age and replacement planning, and total cost of ownership — for one site or all,
// over a date range. Every figure comes from records in the app; where a field isn't recorded (model year, purchase
// price …) the report says how many units have it instead of estimating. One model feeds the screen, the Excel
// workbook (a sheet per section) and the PDF (print / Save as PDF).
import { esc, fmtNum, fmtMoney, fmtPct, isISO, todayISO, addDays, num, norm, downloadXLSXBook, toast } from '@atl/util.js';
import { chart, chartBox } from '@atl/ui.js';
import { SITES, SITE_BLDG, assets, serviceRows, workOrderRows, inspectionRows, hoursRows, downtimeDays, daysBetween, isTruck, isAttachment, isFacility, woOpen, config, lotoRows } from '@atl/mhe.js';

const siteLabel = s => (SITE_BLDG[s] ? \`\${s} (\${SITE_BLDG[s]})\` : s);
const us = iso => (isISO(iso) ? \`\${+iso.slice(5, 7)}/\${+iso.slice(8, 10)}/\${iso.slice(2, 4)}\` : '');
const monLabel = m => new Date(m + '-01T00:00:00Z').toLocaleString('en-US', { month: 'short', year: 'numeric', timeZone: 'UTC' });
const CORRECTIVE = c => !/preventive|inspection/i.test(c || '');
const inRange = (d, from, to) => isISO(d) && d >= from && d <= to;

export const PRESETS = [['month', 'This month'], ['3m', 'Last 3 months'], ['ytd', 'Year to date'], ['12m', 'Last 12 months'], ['lastyear', 'Last year'], ['all', 'All records']];
export function presetRange(p) {
  const t = todayISO(), y = +t.slice(0, 4);
  return { month: [t.slice(0, 8) + '01', t], '3m': [addDays(t, -91), t], ytd: [\`\${y}-01-01\`, t], '12m': [addDays(t, -365), t], lastyear: [\`\${y - 1}-01-01\`, \`\${y - 1}-12-31\`], all: ['2000-01-01', t] }[p] || [\`\${y}-01-01\`, t];
}

/** The whole report as sections: { id, title, note, cols: [{h, t}], rows: [[…]], total? }. */
export function buildReport(site, from, to) {
  const cfg = config(), today = todayISO(), end = to > today ? today : to;
  const days = Math.max(1, daysBetween(from, end) + 1);
  const all = assets().filter(a => !site || a.site === site), A = all.filter(a => a.status !== 'Retired');
  const byId = new Map(all.map(a => [a.assetId, a]));
  const svc = serviceRows().filter(s => (!site || s.site === site) && norm(s.status) !== 'CANCELLED' && inRange(s.serviceDate, from, to));
  const wos = workOrderRows().filter(w => (!site || w.site === site) && inRange(w.reportedDate, from, to));
  const insp = inspectionRows().filter(i => (!site || i.site === site) && inRange(i.date, from, to));
  const hrs = hoursRows().filter(h => h.check === 'OK' && typeof h.hoursUsed === 'number' && (!site || h.site === site) && inRange(h.weekEnding, from, to));
  const sites = SITES.filter(s => all.some(a => a.site === s));
  const cost = rows => rows.reduce((t, s) => t + num(s.amount), 0);
  const down = new Map(A.map(a => [a.assetId, downtimeDays(a, from, addDays(end, 1))]));
  const downTotal = [...down.values()].reduce((t, n) => t + n, 0);
  const tracked = A.filter(a => (a.statusHistory || []).length).length;
  const hrsBy = new Map(); for (const h of hrs) hrsBy.set(h.assetId, (hrsBy.get(h.assetId) || 0) + h.hoursUsed);
  const weeks = new Set(hrs.map(h => h.weekEnding)).size, trucks = A.filter(isTruck);
  const sec = [];

  // 1. Summary
  const completed = wos.filter(w => w.status === 'Completed'), est = completed.filter(w => w.estCost !== '' && w.estCost != null && w.actualCost !== '' && w.actualCost != null);
  sec.push({ id: 'summary', title: 'Summary', cols: [{ h: 'Measure', t: 'text' }, { h: 'Value', t: 'text' }, { h: 'How it is worked out', t: 'text' }], rows: [
    ['Units in the fleet', fmtNum(A.length), \`\${fmtNum(all.length - A.length)} retired not counted\`],
    ['In service / out of service now', \`\${fmtNum(A.filter(a => a.status === 'In Service').length)} / \${fmtNum(A.filter(a => a.status === 'Out of Service').length)}\`, 'Current status of each unit'],
    ['Availability (recorded)', tracked ? fmtPct(1 - downTotal / (A.length * days), 1) : 'n/a', tracked ? \`1 − out-of-service days (\${fmtNum(downTotal)}) ÷ unit-days (\${fmtNum(A.length)} × \${fmtNum(days)}), from status changes recorded in the app; the \${fmtNum(A.length - tracked)} units with no status change recorded count as available\` : 'No status changes recorded yet in this range'],
    ['Maintenance spend', fmtMoney(cost(svc)), \`\${fmtNum(svc.filter(s => num(s.amount)).length)} invoices / completed work orders with a cost, by service date\`],
    ['Work orders opened / completed', \`\${fmtNum(wos.length)} / \${fmtNum(completed.length)}\`, \`\${fmtNum(wos.filter(w => woOpen(w.status)).length)} of those still open\`],
    ['Actual vs estimated cost', est.length ? fmtMoney(est.reduce((t, w) => t + num(w.actualCost) - num(w.estCost), 0)) : 'n/a', est.length ? \`\${fmtNum(est.length)} completed work orders with both an estimate and an actual (positive = over estimate)\` : 'No completed work order has both an estimate and an actual cost'],
    ['Lockouts applied', fmtNum(lotoRows().filter(l => (!site || l.site === site) && inRange(l.appliedDate, from, to)).length), (n => \`\${fmtNum(lotoRows().filter(l => (!site || l.site === site) && l.active).length)} locked out now · \${fmtNum(n)} supervisor removal\${n === 1 ? '' : 's'} in range\`)(lotoRows().filter(l => (!site || l.site === site) && l.supRemoval && inRange(l.releasedDate, from, to)).length)],
    ['Inspections recorded', fmtNum(insp.length), \`\${fmtNum(insp.filter(i => /^fail/i.test(i.result || '')).length)} failed · \${fmtNum(insp.filter(i => i.deficiency).length)} with deficiencies\`],
    ['Avg hours per truck per week', weeks && hrsBy.size ? fmtNum([...hrsBy.values()].reduce((t, n) => t + n, 0) / hrsBy.size / weeks, 1) : 'n/a', weeks ? \`OK hour readings, \${fmtNum(hrsBy.size)} trucks over \${fmtNum(weeks)} week\${weeks === 1 ? '' : 's'}\` : 'No OK hour readings in this range'],
  ] });

  // 2. Fleet by warehouse  3. Fleet by type
  sec.push({ id: 'site', title: 'Fleet by warehouse', cols: [{ h: 'Site', t: 'text' }, { h: 'Units', t: 'num' }, { h: 'Trucks', t: 'num' }, { h: 'Attachments', t: 'num' }, { h: 'Facility', t: 'num' }, { h: 'In service', t: 'num' }, { h: 'Out of service', t: 'num' }, { h: 'Retired', t: 'num' }, { h: 'Open work orders', t: 'num' }, { h: 'Spend in range', t: 'money' }],
    rows: sites.map(s => { const u = A.filter(a => a.site === s); return [siteLabel(s), u.length, u.filter(isTruck).length, u.filter(isAttachment).length, u.filter(isFacility).length, u.filter(a => a.status === 'In Service').length, u.filter(a => a.status === 'Out of Service').length, all.filter(a => a.site === s && a.status === 'Retired').length, u.reduce((t, a) => t + a.openWO, 0), cost(svc.filter(x => x.site === s))]; }), total: true });
  const fams = [...new Set(all.map(a => a.family || '(not recorded)'))]; // retired units' spend still counts toward their type
  sec.push({ id: 'type', title: 'Fleet by equipment type', cols: [{ h: 'Type', t: 'text' }, { h: 'Units', t: 'num' }, { h: 'In service', t: 'num' }, { h: 'Out of service', t: 'num' }, { h: 'Avg age (yrs)', t: 'num1' }, { h: 'Age known', t: 'num' }, { h: 'Spend in range', t: 'money' }],
    rows: fams.map(f => { const u = A.filter(a => (a.family || '(not recorded)') === f), aged = u.filter(a => a.age !== ''); return [f, u.length, u.filter(a => a.status === 'In Service').length, u.filter(a => a.status === 'Out of Service').length, aged.length ? aged.reduce((t, a) => t + a.age, 0) / aged.length : '', aged.length, cost(svc.filter(s => (byId.get(s.assetId)?.family || '(not recorded)') === f))]; }).filter(r => r[1] || r[6]).sort((x, y) => y[1] - x[1]), total: true,
    note: 'Units = active units (retired left out); spend includes every unit of that type, retired ones too.' });

  // 4. Cost by month  5. Cost by warehouse
  const months = [...new Set(svc.map(s => s.serviceDate.slice(0, 7)))].sort();
  sec.push({ id: 'month', title: 'Maintenance cost by month', chart: true, cols: [{ h: 'Month', t: 'text' }, { h: 'Events', t: 'num' }, { h: 'Preventive', t: 'money' }, { h: 'Repairs & other', t: 'money' }, { h: 'Inspection', t: 'money' }, { h: 'Total', t: 'money' }],
    rows: months.map(m => { const r = svc.filter(s => s.serviceDate.startsWith(m)); return [monLabel(m), r.length, cost(r.filter(s => /preventive/i.test(s.category))), cost(r.filter(s => CORRECTIVE(s.category))), cost(r.filter(s => /inspection/i.test(s.category))), cost(r)]; }), total: true,
    note: 'Service Log invoices and completed work orders (actual cost) by service / completion date. Months with no cost recorded are left out.' });
  sec.push({ id: 'sitecost', title: 'Maintenance cost by warehouse', cols: [{ h: 'Site', t: 'text' }, { h: 'Events', t: 'num' }, { h: 'Preventive', t: 'money' }, { h: 'Repairs & other', t: 'money' }, { h: 'Total', t: 'money' }, { h: 'Units', t: 'num' }, { h: 'Cost per unit', t: 'money' }],
    rows: sites.map(s => { const r = svc.filter(x => x.site === s), n = A.filter(a => a.site === s).length; return [siteLabel(s), r.length, cost(r.filter(x => /preventive/i.test(x.category))), cost(r.filter(x => !/preventive/i.test(x.category))), cost(r), n, n ? cost(r) / n : '']; }), total: true });

  // 6. Downtime
  const downRows = A.filter(a => down.get(a.assetId) > 0 || a.status === 'Out of Service').map(a => {
    const outs = (a.statusHistory || []).filter(h => h.to === 'Out of Service' && inRange(h.date, from, to)).length;
    return [a.assetId, siteLabel(a.site), a.family || '', down.get(a.assetId), outs, a.status, a.statusReason || ''];
  }).sort((x, y) => y[3] - x[3]);
  sec.push({ id: 'downtime', title: 'Downtime', cols: [{ h: 'Unit', t: 'id' }, { h: 'Site', t: 'text' }, { h: 'Type', t: 'text' }, { h: 'Days out of service', t: 'num' }, { h: 'Times taken out', t: 'num' }, { h: 'Status now', t: 'pill' }, { h: 'Latest reason', t: 'text' }], rows: downRows, total: true,
    note: \`From status changes recorded in the app (\${fmtNum(tracked)} of \${fmtNum(A.length)} units have a status history). Time before the app started tracking status is not counted.\` });

  // 7. Repair frequency
  const rep = svc.filter(s => CORRECTIVE(s.category)), repBy = new Map(); for (const s of rep) (repBy.get(s.assetId) || repBy.set(s.assetId, []).get(s.assetId)).push(s);
  sec.push({ id: 'repairs', title: 'Repair frequency', cols: [{ h: 'Unit', t: 'id' }, { h: 'Site', t: 'text' }, { h: 'Type', t: 'text' }, { h: 'Repairs', t: 'num' }, { h: 'Last repair', t: 'date' }, { h: 'Repair cost', t: 'money' }, { h: 'Hours used', t: 'num' }, { h: 'Repairs per 1,000 hrs', t: 'num1' }],
    rows: [...repBy.entries()].map(([id, r]) => { const a = byId.get(id) || {}, h = hrsBy.get(id) || 0; return [id || '(unknown)', siteLabel(a.site || r[0].site), a.family || '', r.length, r.map(s => s.serviceDate).sort().at(-1), cost(r), h || '', h ? r.length / h * 1000 : '']; }).sort((x, y) => y[3] - x[3] || y[5] - x[5]), total: true,
    note: 'Repairs = every service event or completed work order that is not Preventive Maintenance or Inspection (repairs, tires, batteries, attachments, damage). Hours used = OK hour readings in the range.' });

  // 8. Inspection compliance
  const need = A.filter(a => isTruck(a) && a.status === 'In Service');
  sec.push({ id: 'insp', title: 'Inspection compliance', cols: [{ h: 'Site', t: 'text' }, { h: 'Trucks in service', t: 'num' }, { h: 'Inspected in range', t: 'num' }, { h: 'Coverage', t: 'pct' }, { h: 'Inspections', t: 'num' }, { h: 'Failed', t: 'num' }, { h: 'With deficiencies', t: 'num' }, { h: 'Corrective actions open', t: 'num' }, { h: 'Overdue now', t: 'num' }, { h: 'None on record', t: 'num' }],
    rows: sites.filter(s => need.some(a => a.site === s) || insp.some(i => i.site === s)).map(s => {
      const t = need.filter(a => a.site === s), i = insp.filter(x => x.site === s), done = new Set(i.map(x => x.assetId));
      return [siteLabel(s), t.length, t.filter(a => done.has(a.assetId)).length, t.length ? t.filter(a => done.has(a.assetId)).length / t.length : '', i.length, i.filter(x => /^fail/i.test(x.result || '')).length, i.filter(x => x.deficiency).length, inspectionRows().filter(x => x.site === s && x.caOpen).length, t.filter(a => a.inspStatus === 'Overdue').length, t.filter(a => a.inspStatus === 'None on record').length];
    }), total: true,
    note: \`Powered trucks in service need a pre-shift inspection each day they are used (OSHA 1910.178(q)(7)). Coverage = trucks with at least one inspection in the range. Overdue = no inspection for more than \${fmtNum(cfg.inspOverdueDays)} days (Settings).\` });

  // 9. Lockout / tagout: every lockout applied in the range, plus any still on that began earlier.
  const lotos = lotoRows().filter(l => (!site || l.site === site) && (inRange(l.appliedDate, from, to) || (l.active && l.appliedDate < from)));
  const fmtWhen = iso => (iso ? new Date(iso).toLocaleString('en-US', { month: 'numeric', day: 'numeric', year: '2-digit', hour: 'numeric', minute: '2-digit' }) : '');
  sec.push({ id: 'loto', title: 'Lockout / tagout log', cols: [{ h: 'LOTO #', t: 'text' }, { h: 'Unit', t: 'id' }, { h: 'Site', t: 'text' }, { h: 'Status', t: 'text' }, { h: 'Locked out', t: 'text' }, { h: 'Released', t: 'text' }, { h: 'Hours locked out', t: 'num1' },
      { h: 'Reason / work', t: 'text' }, { h: 'Method', t: 'text' }, { h: 'Locks', t: 'num' }, { h: 'People', t: 'text' }, { h: 'Verified', t: 'text' }, { h: 'Released by', t: 'text' }, { h: 'Supervisor removal', t: 'text' }, { h: 'Missing', t: 'text' }],
    rows: lotos.map(l => [l.id, l.assetId, siteLabel(l.site), l.status, fmtWhen(l.appliedAt), fmtWhen(l.releasedAt), l.hoursOn, l.reason || '', l.method || '', l.locks.length, l.people, norm(l.verified) === 'Y' ? 'Yes' : 'No', l.releasedBy || '', l.supRemoval ? 'Yes' : '', l.gapText]),
    note: \`\${fmtNum(lotos.filter(l => l.active).length)} still locked out. Locks = every lock put on during the lockout (group lockout and shift handovers included). Supervisor removal = a lock removed by someone other than the person who applied it (OSHA 1910.147(e)(3)). Missing = checks not yet recorded on an active lockout.\` });

  // 10. Age & replacement planning
  const aged = A.filter(a => a.age !== '');
  sec.push({ id: 'age', title: 'Age & replacement planning', cols: [{ h: 'Unit', t: 'id' }, { h: 'Site', t: 'text' }, { h: 'Type', t: 'text' }, { h: 'Year', t: 'text' }, { h: 'Age', t: 'num' }, { h: 'Expected life', t: 'num' }, { h: 'Replace in', t: 'num' }, { h: 'Hour meter', t: 'num' }, { h: 'Cost last 12 mo', t: 'money' }, { h: 'Current value', t: 'money' }, { h: 'Flag', t: 'text' }],
    rows: aged.map(a => { const left = a.replaceYear - +today.slice(0, 4), v = num(a.currentValue);
      const flag = left <= 0 ? 'Past expected life' : left <= 2 ? 'Plan replacement' : v && a.spend12 > v * 0.5 ? 'Repair cost > 50% of value' : '';
      return [a.assetId, siteLabel(a.site), a.family || '', String(a.modelYear || a.purchaseDate?.slice(0, 4) || ''), a.age, a.lifeYears, left, a.hourMeter, a.spend12, v || '', flag]; }).sort((x, y) => x[6] - y[6]),
    note: \`\${fmtNum(aged.length)} of \${fmtNum(A.length)} units have a model year or purchase date — the others can't be aged until it is recorded (Edit details ▸ Year / Purchase date). Expected life: the unit's own, else \${fmtNum(cfg.lifeYears)} years (Settings).\` });

  // 10. Total cost of ownership
  const tco = all.map(a => { const buy = num(a.purchasePrice), lp = num(a.leasePaid), m = a.spendAll, tot = buy + lp + m; return [a.assetId, siteLabel(a.site) + (a.status === 'Retired' ? ' (retired)' : ''), a.family || '', buy || '', lp || '', m || '', tot, a.hourMeter, a.hourMeter ? tot / a.hourMeter : '']; }).filter(r => r[6] > 0).sort((x, y) => y[6] - x[6]);
  sec.push({ id: 'tco', title: 'Total cost of ownership', cols: [{ h: 'Unit', t: 'id' }, { h: 'Site', t: 'text' }, { h: 'Type', t: 'text' }, { h: 'Purchase price', t: 'money' }, { h: 'Lease paid to date', t: 'money' }, { h: 'Maintenance (all on file)', t: 'money' }, { h: 'Total', t: 'money' }, { h: 'Hour meter', t: 'num' }, { h: 'Cost per hour', t: 'money2' }], rows: tco, total: true,
    note: \`All-time figures (not limited to the date range): purchase price, lease payments made to date and every maintenance cost on file. Purchase price is recorded for \${fmtNum(A.filter(a => num(a.purchasePrice)).length)} of \${fmtNum(A.length)} units and lease payments for \${fmtNum(A.filter(a => num(a.leasePaid)).length)}, so a unit's total is only as complete as its record.\` });
  return { site, from, to: end, sections: sec, months, svc };
}

const fmt = (v, t) => {
  if (v === '' || v == null) return '';
  switch (t) {
    case 'money': return fmtMoney(+v); case 'money2': return fmtMoney(+v, 2); case 'num': return typeof v === 'number' ? fmtNum(v) : esc(v); case 'num1': return typeof v === 'number' ? fmtNum(v, 1) : esc(v);
    case 'pct': return fmtPct(+v, 0); case 'date': return us(v); case 'id': return \`<a class="mono" href="#/mhe?tab=unit&id=\${encodeURIComponent(v)}">\${esc(v)}</a>\`;
    case 'pill': return \`<span class="pill \${v === 'Out of Service' ? 'bad' : v === 'In Service' ? 'good' : 'neutral'}">\${esc(v)}</span>\`;
    default: return esc(v);
  }
};
const numeric = t => ['money', 'money2', 'num', 'num1', 'pct'].includes(t);
function totals(s) {
  // Only amounts and counts add up; ages, meters and per-unit / per-hour ratios don't.
  return s.cols.map((c, i) => i === 0 ? 'Total' : ['money', 'num'].includes(c.t) && !/^(Age|Expected life|Replace in|Hour meter|Avg|Last)|\\bper\\b/i.test(c.h) ? s.rows.reduce((t, r) => t + num(r[i]), 0) : '');
}
export function sectionHtml(s, { links = true } = {}) {
  const t = s.total && s.rows.length > 1 ? totals(s) : null;
  return \`<section class="card rp-sec" id="rp-\${s.id}"><h3>\${esc(s.title)} \${s.rows.length && s.id !== 'summary' ? \`<small>\${fmtNum(s.rows.length)} row\${s.rows.length === 1 ? '' : 's'}</small>\` : ''}</h3>
    \${s.chart && s.rows.length ? \`<div class="rp-chart">\${chartBox('ch-rp-month', 240, 'Maintenance cost per month stacked by preventive, repairs and inspection')}</div>\` : ''}
    \${s.rows.length ? \`<div class="table-wrap"><table class="grid rp-table"><thead><tr>\${s.cols.map(c => \`<th class="\${numeric(c.t) ? 'num' : ''}">\${esc(c.h)}</th>\`).join('')}</tr></thead><tbody>
      \${s.rows.map(r => \`<tr>\${r.map((v, i) => \`<td class="\${numeric(s.cols[i].t) ? 'num' : ''}" data-l="\${esc(s.cols[i].h)}">\${s.id === 'summary' && i === 1 ? \`<b>\${esc(v)}</b>\` : fmt(v, links ? s.cols[i].t : s.cols[i].t === 'id' ? 'text' : s.cols[i].t)}</td>\`).join('')}</tr>\`).join('')}</tbody>
      \${t ? \`<tfoot><tr>\${t.map((v, i) => \`<td class="\${numeric(s.cols[i].t) ? 'num' : ''}">\${i === 0 ? '<b>Total</b>' : v === '' ? '' : \`<b>\${fmt(v, s.cols[i].t)}</b>\`}</td>\`).join('')}</tr></tfoot>\` : ''}</table></div>\`
      : \`<p class="muted mhe-pad">No records for this section in the chosen site and dates.</p>\`}
    \${s.note ? \`<p class="rs-foot">\${esc(s.note)}</p>\` : ''}</section>\`;
}
export function drawReportChart(R) {
  const m = R.sections.find(s => s.id === 'month'); if (!m?.rows.length) return;
  chart('ch-rp-month', { type: 'bar', data: { labels: m.rows.map(r => r[0]), datasets: [['Preventive', 2, '#1f4a85'], ['Repairs & other', 3, '#c0392b'], ['Inspection', 4, '#c0904d']].map(([l, i, c]) => ({ label: l, data: m.rows.map(r => r[i] || null), backgroundColor: c, stack: 's', borderRadius: 1 })) },
    options: { plugins: { tooltip: { mode: 'index', filter: t => t.parsed.y > 0, callbacks: { label: t => \`\${t.dataset.label}: \${fmtMoney(t.parsed.y)}\`, footer: it => \`Total \${fmtMoney(it.reduce((a, t) => a + t.parsed.y, 0))}\` } } },
      scales: { x: { stacked: true, grid: { display: false } }, y: { stacked: true, beginAtZero: true, ticks: { callback: v => fmtMoney(v) } } } } });
}
const scopeText = R => \`\${R.site ? siteLabel(R.site) : 'All sites'} · \${us(R.from)} – \${us(R.to)}\`;
const fileStem = R => \`MHE Fleet Report \${R.site ? R.site.replace(/[^\\w ]/g, '') + ' ' : ''}\${R.from} to \${R.to}\`;

export function exportExcel(R) {
  const sheets = R.sections.map(s => {
    const t = s.total && s.rows.length > 1 ? totals(s) : null;
    return { name: s.title.replace(/&/g, 'and').replace(/\\s*\\/\\s*/g, '-'), headers: s.cols.map(c => c.h), rows: [...s.rows.map(r => r.map((v, i) => (s.cols[i].t === 'pct' && typeof v === 'number' ? +(v * 100).toFixed(1) : typeof v === 'number' ? +v.toFixed(2) : v))), ...(t ? [t.map(v => (typeof v === 'number' ? +v.toFixed(2) : v))] : [])] };
  });
  sheets.unshift({ name: 'Report', headers: ['MHE Fleet Report', ''], rows: [['Scope', scopeText(R)], ['Created', new Date().toLocaleString('en-US')], ['Source', 'Atlanta Ops web app — MHE Fleet records; nothing estimated'], ...R.sections.filter(s => s.note).map(s => [s.title, s.note])] });
  downloadXLSXBook(\`\${fileStem(R)}.xlsx\`, sheets);
  toast('Report exported to Excel');
}
export function exportPdf(R) {
  const img = document.getElementById('ch-rp-month')?.toDataURL?.('image/png');
  const w = window.open('', '_blank');
  if (!w) return toast('Allow pop-ups for this site to save the PDF', 'bad');
  const body = R.sections.map(s => sectionHtml(s, { links: false }).replace(/<div class="rp-chart">[\\s\\S]*?<\\/canvas><\\/div><\\/div>/, img && s.chart ? \`<img class="rp-img" src="\${img}" alt="Maintenance cost by month">\` : '')).join('');
  w.document.write(\`<!doctype html><html><head><meta charset="utf-8"><title>\${esc(fileStem(R))}</title><style>
    body{font:12px 'Segoe UI',system-ui,sans-serif;color:#1c232d;margin:24px}h1{font-size:18px;margin:0 0 2px}h1+p{color:#5b6478;margin:0 0 14px}
    .card{break-inside:avoid;margin:0 0 16px}h3{font-size:13px;margin:0 0 6px;border-bottom:2px solid #c0392b;padding-bottom:3px}h3 small{font-weight:400;color:#5b6478}
    table{border-collapse:collapse;width:100%}th,td{border-bottom:1px solid #e3e6ec;padding:3px 6px;text-align:left;vertical-align:top}th{background:#222b36;color:#fff;font-weight:600}
    .num{text-align:right}tfoot td{border-top:2px solid #222b36}.rs-foot{color:#5b6478;font-style:italic;font-size:11px;margin:4px 0 0}.pill{font-weight:600}.rp-img{max-width:100%;height:auto;margin:4px 0}
    .muted{color:#5b6478}@page{size:landscape;margin:12mm}</style></head><body><h1>MHE Fleet Report</h1><p>\${esc(scopeText(R))} · created \${esc(new Date().toLocaleString('en-US'))} · from the records in the Atlanta Ops app</p>\${body}</body></html>\`);
  w.document.close(); w.focus(); setTimeout(() => w.print(), 300);
}`]);

